<script setup>import PartnerLayout from '@/Layouts/PartnerLayout.vue';import Pagination from '@/Components/Partner/Pagination.vue';import {Link} from '@inertiajs/vue3';defineProps({payments:Object});</script><template><PartnerLayout title="Client payments"><p class="mb-5 text-slate-600">Online and offline payment history for your clients. Open an invoice to pay online or submit a payment for verification.</p><Link :href="route('partner.invoices')" class="mb-6 inline-block font-bold text-cyan-700">View invoices</Link><div class="space-y-4"><article v-for="payment in payments.data" :key="payment.uuid" class="rounded-xl bg-white p-5"><h2 class="font-bold">{{ payment.payment_number }} ? {{ payment.customer.name }}</h2><p class="mt-2">{{ payment.currency }} {{ payment.amount }} ? {{ payment.status }} ? {{ payment.payment_method }}</p><p class="mt-2 break-words text-sm text-slate-600">Reference: {{ payment.transaction_reference }}</p></article><p v-if="!payments.data.length">No payments yet.</p></div><Pagination :page="payments"/></PartnerLayout></template>
